INSERT INTO medical_dictionary_entries (canonical_name, normalized_canonical_name, medical_category_id, status, default_confidence, notes, approved_at, created_at, updated_at)
SELECT se.canonical_name, se.normalized_canonical_name, mc.id, 'APPROVED', se.default_confidence, se.notes, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
FROM seed_entries se
JOIN medical_categories mc ON mc.code = se.category_code AND mc.active = TRUE AND mc.deleted = FALSE
ON CONFLICT (normalized_canonical_name) DO UPDATE SET
    medical_category_id = EXCLUDED.medical_category_id,
    status = 'APPROVED',
    default_confidence = GREATEST(medical_dictionary_entries.default_confidence, EXCLUDED.default_confidence),
    updated_at = CURRENT_TIMESTAMP;


