INSERT INTO medical_dictionary_synonyms (entry_id, synonym, normalized_synonym, synonym_type, language, active, created_at, updated_at)
SELECT e.id, ss.synonym, ss.normalized_synonym, ss.synonym_type, ss.language, TRUE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
FROM seed_synonyms ss
JOIN medical_dictionary_entries e ON e.normalized_canonical_name = ss.entry_normalized_name
ON CONFLICT (normalized_synonym) DO NOTHING;


